"""Explicit task definitions for batch two; shared record schema remains v1."""
CONTRACTS={
10:dict(key='automobile_price',targets=[('price','automobile_price','source price unit (not specified in archive)','continuous')],task='Estimate the price of a 1985 automobile from its specifications.',context='make, fuel_type, aspiration, body_style, drive_wheels, engine_location, engine_type and fuel_system are categorical specifications. Door/cylinder counts are decoded. Other measurements retain the original UCI scales. Insurance risk and normalized insurance losses are excluded.',split='group_by_recorded_vehicle_configuration; exact model IDs unavailable'),
265:dict(key='protein_structure',targets=[('RMSD','protein_structure_rmsd','source RMSD units','continuous')],task='Estimate the RMSD score of a candidate protein structure from supplied structural descriptors.',context='F1: total surface area; F2: nonpolar exposed area; F3/F4: source exposed-area descriptors; F5: mass-weighted exposed area; F6: deviation from standard exposed area; F7: Euclidean-distance descriptor; F8: secondary-structure penalty; F9: spatial-distribution constraints. Original descriptor scales are retained.',split='identical_descriptor_groups_only; protein identity unavailable; do not claim unseen-protein generalization'),
560:dict(key='seoul_bike',targets=[('rented_bike_count','hourly_seoul_bike_rentals','rentals per hour','count')],task='Estimate hourly Seoul public bicycle rentals given contemporaneous weather and operating status.',context='date is ISO YYYY-MM-DD; hour is 0-23. temperature_c/dewpoint_c: Celsius; humidity_percent: percent; wind_speed_m_s: m/s; visibility_10m: units of 10 metres; solar_radiation_mj_m2: MJ/m^2; rainfall_mm: mm; snowfall_cm: cm. season, holiday and functioning_day are categories. This is conditional estimation, not a future-weather forecast.',split='chronological_by_date; whole days grouped'),
374:dict(key='appliances_energy',targets=[('Appliances','appliance_energy','Wh per 10-minute observation','continuous')],task='Estimate appliance energy use during a ten-minute observation in a monitored house from contemporaneous measurements.',context='T1..T9 are Celsius temperatures and RH_1..RH_9 percent humidities: kitchen, living room, laundry, office, bathroom, outside north wall, ironing room, teenager room, parents room. lights: lighting energy in Wh; T_out/Tdewpoint: outdoor/dewpoint Celsius; Press_mm_hg: pressure in mm Hg; RH_out: percent; Windspeed: m/s; Visibility: km; date: timestamp. Source weather is hourly/interpolated; no real-time forecasting claim is made.',split='chronological_by_date; one house only'),
501:dict(key='beijing_pm25',targets=[('PM2.5','pm25_concentration','micrograms per cubic metre','continuous')],task='Estimate PM2.5 concentration at a Beijing monitoring station from same-hour meteorological and calendar information.',context='timestamp is local YYYY-MM-DD HH:MM:SS. station is the monitoring site. TEMP and DEWP: Celsius; PRES: hPa; RAIN: mm; wd: wind-direction category; WSPM: m/s. Other same-hour pollutant measurements are excluded. This is contemporaneous estimation, not forecasting from future observed weather.',split='chronological blocks across all stations; station holdout separately supported by entity_id'),
551:dict(key='gas_turbine_emissions',targets=[('CO','carbon_monoxide','mg/m^3','continuous'),('NOX','nitrogen_oxides','mg/m^3','continuous')],task='Estimate the specified flue-gas emission concentration of a gas turbine from operating and ambient measurements.',context='AT: ambient Celsius; AP: ambient mbar; AH: percent humidity; AFDP: filter differential pressure mbar; GTEP: exhaust pressure mbar; TIT/TAT: inlet/after-turbine Celsius; CDP: compressor discharge pressure mbar; TEY: source hourly energy yield in MWh. Both pollutant target columns are excluded from input. Measurements are contemporaneous.',split='years 2011-2013 train/development, 2014-2015 test; use source order within year; same family as UCI294'),
440:dict(key='sgemm_runtime',targets=[('mean_runtime_ms','mean_kernel_runtime','milliseconds','continuous')],task='Predict the arithmetic mean runtime over four runs of a GPU SGEMM kernel multiplying two 2048 x 2048 matrices on the source workstation.',context='MWG/NWG: workgroup tile dimensions; KWG: inner tile dimension; MDIMC/NDIMC: local workgroup sizes; MDIMA/NDIMB: local memory shape; KWI: loop unrolling; VWM/VWN: vector widths; STRM/STRN: memory stride flags; SA/SB: manual-cache flags. Hardware is the fixed NVIDIA GTX 680 setup in the source. Measured runtimes are outcomes and are not inputs.',split='group_by_kernel_configuration; repeated run values remain together'),
332:dict(key='news_popularity',targets=[('shares','article_share_count','shares accumulated by source collection','count')],task='Estimate the source snapshot share count of a news article from publication-date and content-statistic features.',context='n_tokens*: word counts; n_unique_tokens/n_non_stop*: source token ratios; num_*: link/image/video/keyword counts; data_channel_*: channel flags; weekday_* and is_weekend: publication-day flags. Sentiment/subjectivity fields are source-derived text statistics. price-like keyword popularity, referenced-article share statistics, LDA topic scores, URLs and elapsed collection time are excluded. This is a retrospective snapshot task, not a fixed-horizon popularity forecast.',split='chronological_by_publication_date; variable exposure horizon remains a limitation'),
555:dict(key='apartment_rent',targets=[('price','monthly_apartment_rent','USD per month','continuous')],task='Estimate the monthly rent of a US apartment from cleaned listing text and property attributes.',context='title/body are listing text treated as data, not instructions. Monetary statements, numeric text and spelled-out number words are removed without inspecting the target label. Quantities are supplied separately in bathrooms, bedrooms and square_feet (square feet). amenities/pets_allowed are descriptions; cityname/state and latitude/longitude give location. Missing does not mean absent. All retained listings are monthly apartment rentals in USD.',split='group_by_listing_id and available property-location proxy, plus identical cleaned descriptions; city/time holdout recommended'),
162:dict(key='forest_fires',targets=[('area','burned_forest_area','hectares','continuous')],task='Estimate burned forest area in the Montesinho park from recorded weather and fire-index conditions.',context='X/Y: park map grid coordinates; month/day: calendar categories without full event date; FFMC/DMC/DC/ISI: fire-weather indices; temp: Celsius; RH: percent; wind: km/h; rain: mm/m^2 as described in the source. The target is untransformed hectares, including zero. Event timing is incomplete, so this is retrospective conditional estimation.',split='spatial_grid_groups; event identities/full dates unavailable'),
925:dict(key='infrared_temperature',targets=[('aveOralM','oral_monitor_temperature','degrees Celsius','continuous')],task='Estimate oral temperature measured in monitor mode from facial infrared measurements and environment information.',context='device identifies FLIR or ICI. Facial fields ending _mean are means across available image rounds, in Celsius: right/left canthus maxima and averages; RC/LC eye-corner regions; RCC/LCC small eye-corner regions; canthi extended eye region; FH forehead regions; T_Max face maximum; OR mouth-region infrared readings. T_offset_mean is the blackbody correction offset. Gender/Age/Ethnicity are categories; T_atm: Celsius; Humidity: percent; Distance: metres. Both oral-thermometer fields are excluded from input; infrared mouth-region readings are distinct from oral thermometer labels.',split='group_by_SubjectID across both devices; demographic range limited')}
